<script setup>
import { onMounted,ref,watch } from 'vue'
import { Drawer as ADrawer,Dropdown as ADropdown,Menu as AMenu,MenuItem as AMenuItem } from 'ant-design-vue'
import {MoreHorizontal} from '../icons'
import {dateTime,confirmAction} from '../ui'
import { api,can,sessionUser } from '../api'
const users=ref([]),roles=ref([]),points=ref([]),kbs=ref([]),error=ref(''),success=ref(''),dialog=ref(''),saving=ref(false),target=ref(null),temporary=ref('')
const form=ref({}),roleForm=ref({}),grants=ref({}),baseline=ref('')
const snapshot=()=>JSON.stringify({form:form.value,role:roleForm.value,grants:grants.value})
watch(dialog,()=>{baseline.value=snapshot()})
let closing=false
async function closeDialog(){if(saving.value||closing)return;closing=true;try{if(dialog.value!=='reset'&&snapshot()!==baseline.value&&!await confirmAction('尚有未保存的用户或权限修改，关闭后不会保存。',{title:'放弃修改？',okText:'放弃修改'}))return;dialog.value='';temporary.value='';error.value=''}finally{closing=false}}
async function load(){error.value='';try{[users.value,roles.value]=await Promise.all([api('/api/users'),api('/api/roles')]);if(can('roles.manage'))[points.value,kbs.value]=await Promise.all([api('/api/permissions'),api('/api/knowledge-bases')])}catch(e){error.value=e.message}}
function create(){form.value={username:'',name:'',password:'',role_id:roles.value.find(r=>!r.system_admin)?.id||roles.value[0]?.id};dialog.value='create';error.value=''}
function edit(u){target.value=u;form.value={name:u.name,role_id:u.role_id,status:u.status};dialog.value='edit';error.value=''}
async function submit(){saving.value=true;error.value='';try{if(dialog.value==='create')await api('/api/users',{method:'POST',body:JSON.stringify(form.value)});else await api(`/api/users/${target.value.id}`,{method:'PATCH',body:JSON.stringify(form.value)});dialog.value='';success.value='用户已保存';await load()}catch(e){error.value=e.message}finally{saving.value=false}}
async function reset(u){target.value=u;temporary.value='';dialog.value='reset';error.value=''}
async function resetNow(){saving.value=true;try{const data=await api(`/api/users/${target.value.id}/reset-password`,{method:'POST',body:'{}'});temporary.value=data.temporary_password;success.value=data.message}catch(e){error.value=e.message}finally{saving.value=false}}
function editRole(role){roleForm.value=role?{...role,permissions:[...role.permissions]}:{name:'',permissions:[]};dialog.value='role';error.value=''}
async function saveRole(){saving.value=true;try{await api(roleForm.value.id?`/api/roles/${roleForm.value.id}`:'/api/roles',{method:roleForm.value.id?'PUT':'POST',body:JSON.stringify(roleForm.value)});dialog.value='';success.value='角色及权限点已保存';await load()}catch(e){error.value=e.message}finally{saving.value=false}}
async function authorize(u){target.value=u;error.value='';try{const data=await api(`/api/users/${u.id}/grants`);grants.value={...Object.fromEntries(kbs.value.map(k=>[k.id,''])),...Object.fromEntries(data.map(g=>[g.knowledge_base_id,g.access]))};dialog.value='grants'}catch(e){error.value=e.message}}
async function saveGrants(){saving.value=true;try{const values=Object.entries(grants.value).filter(([,v])=>v).map(([id,access])=>({knowledge_base_id:Number(id),access}));await api(`/api/users/${target.value.id}/grants`,{method:'PUT',body:JSON.stringify({grants:values})});dialog.value='';success.value='知识库授权已更新，检索与下载立即生效'}catch(e){error.value=e.message}finally{saving.value=false}}
onMounted(load)
</script>
<template><div class="page-stack"><div class="page-intro"><div><h2>用户与权限</h2><p>角色控制功能权限；知识库授权控制数据范围，两者同时校验</p></div><button v-if="can('users.manage')" class="primary-button" @click="create">新增用户</button></div><div v-if="error&&!dialog" class="error-banner">{{error}}</div><div v-if="success" class="success-banner">{{success}}</div><div class="card"><div class="card-body table-wrap user-table"><table><thead><tr><th>显示名 / 账号</th><th>角色</th><th>状态</th><th>最近登录</th><th>操作</th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td><strong>{{u.name}}</strong><br/><small>{{u.username}}</small></td><td>{{u.role}}</td><td><span class="badge" :class="u.status==='active'?'green':'red'">{{u.status==='active'?'启用':'停用'}}</span></td><td>{{u.last_login?dateTime(u.last_login):'尚未登录'}}</td><td><div class="table-actions"><button v-if="can('users.manage')" class="text-button" @click="edit(u)">编辑</button><ADropdown :trigger="['click']"><button class="icon-button" :aria-label="'用户操作 '+u.name"><MoreHorizontal/></button><template #overlay><AMenu><AMenuItem v-if="can('users.manage')" @click="reset(u)">重置密码</AMenuItem><AMenuItem v-if="can('roles.manage')&&!u.system_admin" @click="authorize(u)">知识库授权</AMenuItem><AMenuItem v-if="u.system_admin" disabled>全部知识库（管理员）</AMenuItem></AMenu></template></ADropdown></div></td></tr></tbody></table></div></div><section v-if="can('roles.manage')" class="card role-panel"><div class="page-intro"><div><h3>角色与权限点</h3><p>修改后请求立即读取最新角色配置</p></div><button class="primary-button" @click="editRole(null)">新增角色</button></div><article v-for="r in roles" :key="r.id"><div><strong>{{r.name}}</strong><details class="permission-detail"><summary>{{r.permissions.length}} 项功能权限</summary><div class="permission-pills"><span v-for="p in r.permissions" :key="p" class="badge">{{points.find(x=>x.id===p)?.name||p}}</span></div></details></div><button v-if="!r.system_admin" class="secondary-button" @click="editRole(r)">配置权限</button><span v-else class="badge">保留角色</span></article></section>
<ADrawer :open="!!dialog" :width="'min(520px,100vw)'" :mask-closable="!saving" :closable="!saving" @close="closeDialog"><template #title>{{ {create:'新增用户',edit:'编辑用户',role:'角色与权限点',grants:`知识库授权：${target?.name}`,reset:`重置密码：${target?.name}`}[dialog] }}</template><div v-if="error" class="error-banner">{{error}}</div>
<form v-if="['create','edit'].includes(dialog)" @submit.prevent="submit"><div class="modal-body"><label v-if="dialog==='create'" class="field">账号（3–40 位字母、数字、点、下划线）<input v-model="form.username" class="input" pattern="[a-zA-Z0-9_.-]{3,40}" required/></label><label class="field">显示名<input v-model="form.name" class="input" required maxlength="50"/></label><label v-if="dialog==='create'" class="field">初始密码（至少 8 位）<input v-model="form.password" type="password" class="input" minlength="8" maxlength="128" autocomplete="new-password" required/></label><label class="field">角色<select v-model="form.role_id" class="select" required><option v-for="r in roles.filter(r=>sessionUser.system_admin||!r.system_admin)" :key="r.id" :value="r.id">{{r.name}}</option></select></label><label v-if="dialog==='edit'" class="field">状态<select v-model="form.status" class="select"><option value="active">启用</option><option value="disabled">停用（立即退出所有会话）</option></select></label><p v-if="dialog==='create'" class="help">新用户的角色决定功能权限。团队库和私有库需要单独授权。</p></div><div class="modal-footer"><button class="primary-button" :disabled="saving">{{saving?'保存中…':'保存'}}</button></div></form>
<form v-if="dialog==='role'" @submit.prevent="saveRole"><div class="modal-body"><label class="field">角色名<input v-model="roleForm.name" class="input" required maxlength="50"/></label><label v-for="p in points" :key="p.id" class="check-row"><input v-model="roleForm.permissions" type="checkbox" :value="p.id"/>{{p.name}} <small>{{p.id}}</small></label></div><div class="modal-footer"><button class="primary-button" :disabled="saving">保存角色</button></div></form>
<form v-if="dialog==='grants'" @submit.prevent="saveGrants"><div class="modal-body"><p class="help">读取允许检索、问答和下载。维护还允许上传及移除文档。公开库为有读取权限的登录用户提供默认只读访问。</p><label v-for="kb in kbs" :key="kb.id" class="field">{{kb.name}}<select v-model="grants[kb.id]" class="select"><option value="">{{kb.visibility==='public'?'默认只读（公开）':'无授权'}}</option><option value="read">读取</option><option value="write">读取和维护</option></select></label></div><div class="modal-footer"><button class="primary-button" :disabled="saving">保存授权</button></div></form>
<div v-if="dialog==='reset'" class="modal-body"><p>重置将使该用户所有登录会话失效。</p><template v-if="temporary"><p>临时密码仅本次显示，请妥善交给用户：</p><code class="temporary">{{temporary}}</code></template><button v-else class="danger-button" :disabled="saving" @click="resetNow">确认重置并生成临时密码</button></div></ADrawer></div></template>
<style scoped>.user-table{padding-top:10px}.user-table table{min-width:680px}.permission-detail{font-size:12px;color:var(--muted);margin-top:6px}.permission-detail summary{cursor:pointer}.modal-body{padding:12px 0 20px}.modal-footer{padding:12px 0 0}.role-panel{padding:22px}.role-panel article{display:flex;align-items:center;justify-content:space-between;padding:18px 0;gap:15px;border-bottom:1px solid #e2e8ed}.permission-pills{display:flex;flex-wrap:wrap;gap:6px;margin-top:9px}.check-row{display:flex;align-items:center;gap:8px;font-size:14px}.check-row small{color:#6c7c89}.user-modal{max-height:90vh;overflow:auto}.help{font-size:12px;line-height:1.7;color:#617789}.temporary{background:#fff3ca;padding:14px;overflow-wrap:anywhere}</style>
